import pytest

from bloom_packaging import stamp

CHANGELOG = """ros-jazzy-bloom-node (0.0.1-0noble) noble; urgency=high

  * Autogenerated, no changelog for this version found in CHANGELOG.rst.

 -- "jrkre" <jrk.reno@gmail.com>  Thu, 29 Oct 2026 19:41:03 -0000
"""

CONTROL = """Source: ros-jazzy-bloom-node
Build-Depends: debhelper (>= 9.0.0), ros-jazzy-bloom-msgs, ros-jazzy-rclcpp

Package: ros-jazzy-bloom-node
Depends: ${shlibs:Depends}, ${misc:Depends}, ros-jazzy-bloom-msgs, ros-jazzy-rclcpp,
 ros-jazzy-bloom-speech-engines (>= 0.1)
Description: bloom node
 for ROS2
"""


def test_deb_name():
    assert stamp.deb_name('jazzy', 'bloom_speech_engines') == 'ros-jazzy-bloom-speech-engines'


def test_stamp_changelog_changes_only_the_version():
    out = stamp.stamp_changelog(CHANGELOG, '1.0.20~gabc-1')
    assert out.splitlines()[0] == 'ros-jazzy-bloom-node (1.0.20~gabc-1) noble; urgency=high'
    assert out.splitlines()[1:] == CHANGELOG.splitlines()[1:]


def test_stamp_changelog_rejects_garbage():
    with pytest.raises(ValueError):
        stamp.stamp_changelog('nonsense', '1.0')


def test_internal_depends_are_pinned_everything_else_untouched():
    out = stamp.pin_internal_depends(CONTROL, ['ros-jazzy-bloom-msgs', 'ros-jazzy-bloom-speech-engines'], '1.0.20-1')
    assert 'Build-Depends: debhelper (>= 9.0.0), ros-jazzy-bloom-msgs (= 1.0.20-1), ros-jazzy-rclcpp' in out
    assert 'ros-jazzy-bloom-msgs (= 1.0.20-1)' in out
    assert '${shlibs:Depends}' in out and 'ros-jazzy-rclcpp' in out
    # An explicit constraint the author wrote is left alone.
    assert 'ros-jazzy-bloom-speech-engines (>= 0.1)' in out
    # Non-dependency fields keep their multi-line values.
    assert 'Description: bloom node\n for ROS2' in out
    assert out.count('Package: ros-jazzy-bloom-node') == 1 and out.endswith('\n')


def test_local_rosdep_yaml():
    y = stamp.local_rosdep_yaml({'bloom_msgs': 'ros-jazzy-bloom-msgs'}, 'ubuntu', 'noble')
    assert y == 'bloom_msgs:\n  ubuntu:\n    noble: [ros-jazzy-bloom-msgs]\n'
